package data_structures.hashing;
import java.util.*;
import java.util.function.*;
import java.math.*;

public class OpenAddressingHashMap {
public static class Table<K,V> implements Iterable<Map.Entry<K,V>>{private static final Object DELETED=new Object();private Object[] slots;private int count,tombstones;private final ToLongFunction<K> hasher;public Table(){this(Hash::defaultHasher,16);}public Table(ToLongFunction<K> h,int capacity){hasher=h;slots=new Object[Math.max(2,capacity)];}public int size(){return count;}private int index(K k){return (int)Math.floorMod(hasher.applyAsLong(k),slots.length);}@SuppressWarnings("unchecked")private Map.Entry<K,V> entry(int i){return (Map.Entry<K,V>)slots[i];}private int find(K k){int i=index(k);for(int p=0;p<slots.length;p++){if(slots[i]==null)return -1;if(slots[i]!=DELETED&&Objects.equals(entry(i).getKey(),k))return i;i=(i+1)%slots.length;}return -1;}public Table<K,V> set(K k,V v){if((count+tombstones+1)*2>slots.length)resize(slots.length*2);int i=index(k),first=-1;while(slots[i]!=null){if(slots[i]==DELETED){if(first<0)first=i;}else if(Objects.equals(entry(i).getKey(),k)){entry(i).setValue(v);return this;}i=(i+1)%slots.length;}if(first>=0){i=first;tombstones--;}slots[i]=new AbstractMap.SimpleEntry<>(k,v);count++;return this;}public V get(K k){int i=find(k);return i<0?null:entry(i).getValue();}public boolean has(K k){return find(k)>=0;}public boolean delete(K k){int i=find(k);if(i<0)return false;slots[i]=DELETED;count--;tombstones++;return true;}private void resize(int n){List<Map.Entry<K,V>> a=new ArrayList<>();for(var e:this)a.add(e);slots=new Object[n];count=tombstones=0;for(var e:a)set(e.getKey(),e.getValue());}public Iterator<Map.Entry<K,V>> iterator(){List<Map.Entry<K,V>> o=new ArrayList<>();for(int i=0;i<slots.length;i++)if(slots[i]!=null&&slots[i]!=DELETED)o.add(new AbstractMap.SimpleEntry<>(entry(i)));return o.iterator();}}
}
